   110	asn1_get_length_der (const unsigned char *der, int der_len, int *len)
   111	{
   112	  unsigned int ans;
   113	  int k, punt, sum;
   114	
   115	  *len = 0;
   116	  if (der_len <= 0)
   117	    return 0;
   118	
   119	  if (!(der[0] & 128))
   120	    {
   121	      /* short form */
   122	      *len = 1;
   123	      ans = der[0];
   124	    }
   125	  else
   126	    {
   127	      /* Long form */
   128	      k = der[0] & 0x7F;
   129	      punt = 1;
   130	      if (k)
   131	        { /* definite length method */
   132	          ans = 0;
   133	          while (punt <= k && punt < der_len)
   134	            {
   135	              if (INT_MULTIPLY_OVERFLOW (ans, 256))
   136	                return -2;
   137	              ans *= 256;
   138	
   139	              if (INT_ADD_OVERFLOW (ans, ((unsigned) der[punt])))
   140	                return -2;
   141	              ans += der[punt];
   142	              punt++;
   143	            }
   144	        }
   145	      else
   146	        {                       /* indefinite length method */
   147	          *len = punt;
   148	          return -1;
   149	        }
   150	
   151	      *len = punt;
   152	    }
   153	
   154	  sum = ans;
   155	  if (ans >= INT_MAX || INT_ADD_OVERFLOW (sum, (*len)))
   156	    return -2;
   157	  sum += *len;
   158	
   159	  if (sum > der_len)
   160	    return -4;
